import{_ as t,o as a,i as o,a9 as n}from"./chunks/framework.DuwpaNh0.js";const h=JSON.parse('{"title":"Numbers Are Always Floats","description":"","frontmatter":{"title":"Numbers Are Always Floats"},"headers":[],"relativePath":"modules/5-advanced/conductor-interop/1-numbers.md","filePath":"modules/5-advanced/conductor-interop/1-numbers.md","lastUpdated":1787525063000}'),s={name:"modules/5-advanced/conductor-interop/1-numbers.md"};function r(i,e,l,d,u,c){return a(),o("div",null,e[0]||(e[0]=[n('<h1 id="numbers-always-floats-no-exceptions" tabindex="-1">Numbers: always floats, no exceptions <a class="header-anchor" href="#numbers-always-floats-no-exceptions" aria-label="Permalink to &quot;Numbers: always floats, no exceptions&quot;">​</a></h1><blockquote><p>&quot;numerical values coming from modules (including from functions that are passed to/from modules) are always floats. Values passed to modules (including to functions that are passed to/from modules) can be floats and ints; ints are silently converted to floats.&quot; — Martin Henz</p></blockquote><p>Concretely:</p><ul><li>A module&#39;s <code>DataType.NUMBER</code>-declared parameter always receives a JS <code>number</code> (a float), never a <code>bigint</code>, even if the cadet passed a Python <code>int</code> literal. The evaluator converts it before the module ever sees it.</li><li>A module&#39;s <code>DataType.NUMBER</code>-declared return value is likewise always treated as a float on the way back out.</li><li>This holds <strong>regardless of where the number is</strong> — a bare scalar argument, an element inside a list, or a value stored via <code>DataType.OPAQUE</code> and handed back out later. There is no per-position exception.</li></ul><h2 id="why-1-0-instead-of-1-is-a-feature-not-a-bug" tabindex="-1">Why &quot;1.0 instead of 1&quot; is a feature, not a bug <a class="header-anchor" href="#why-1-0-instead-of-1-is-a-feature-not-a-bug" aria-label="Permalink to &quot;Why &quot;1.0 instead of 1&quot; is a feature, not a bug&quot;">​</a></h2><p><code>binary_tree</code>&#39;s <code>entry()</code> on a tree built with <code>make_tree(1, ...)</code> prints <code>1.0</code>, not <code>1</code>, in every evaluator. It&#39;s tempting to see this as something to fix — an earlier iteration of py-slang&#39;s work did exactly that, teaching the evaluator to tag Python ints distinctly and round-trip them through modules unchanged. Martin&#39;s final call reversed this:</p><blockquote><p>&quot;&#39;would print 1.0, not 1&#39; is a feature, not a bug. We should keep integers out of modules.&quot;</p></blockquote><p>The reasoning is practical, not aesthetic:</p><ul><li><strong>Simplicity.</strong> A module never needs an &quot;is this an int or a float?&quot; branch anywhere in its own code.</li><li><strong>Performance.</strong> If modules had to support real integers, module code (all plain JS/TS) would have no choice but to use <code>bigint</code> arithmetic wherever a value <em>might</em> be an int — and <code>bigint</code> arithmetic is meaningfully slower than <code>number</code> arithmetic. Supporting a rare case (a module caring about integer-vs-float) would tax the common case (every numeric computation a module does).</li><li><strong>Portability.</strong> py-slang isn&#39;t the only evaluator a bundle talks to, and future evaluators for other languages may have no <code>bigint</code>-equivalent primitive at all. An interface contract that only ever promises &quot;a float&quot; works for all of them; one that promises &quot;sometimes a real distinct integer type&quot; doesn&#39;t.</li></ul><p>If you&#39;re writing a bundle and want a value to visibly stay an integer across a module round-trip, that&#39;s not something to build — the interface deliberately doesn&#39;t offer it.</p><details class="details custom-block"><summary>Follow-up: full removal of DataType.PAIR</summary><p>While reviewing the PR that settled this, Martin also flagged that <code>DataType.PAIR</code> shouldn&#39;t exist in py-slang at all going forward (see <a href="./2-pairs-and-arrays.html">Pairs and arrays are the same thing</a>) - a follow-up PR has been claimed to remove it entirely, rather than just treat it as interchangeable with <code>DataType.ARRAY</code>.</p></details>',11)]))}const p=t(s,[["render",r]]);export{h as __pageData,p as default};
